const body = $input.first().json.body || {};
const storeName = body.storeName || body.advertiserName || "Store";
const domain = body.domain || "";
const advertiserId = body.advertiserId ? Number(body.advertiserId) : undefined;
const network = body.network || "awin";

const tavilyKey = "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";

// 1. Search coupon sites via Tavily (RetailMeNot, CouponCabin, Slickdeals, merchant)
const query = `${storeName} active coupon codes promo code discounts deals site:retailmenot.com OR site:couponcabin.com OR site:slickdeals.net OR official`;

let searchData = {};
try {
  searchData = await helpers.httpRequest({
    method: 'POST',
    url: 'https://api.tavily.com/search',
    headers: { 'Content-Type': 'application/json' },
    body: {
      api_key: tavilyKey,
      query: query,
      include_answer: 'advanced',
      search_depth: 'advanced',
      max_results: 6
    },
    json: true
  });
} catch (e) {
  searchData = { answer: "", results: [] };
}

const answerText = searchData.answer || "";
const results = searchData.results || [];

const deals = [];
const seenCodes = new Set();
const seenTitles = new Set();

// Helper to extract expiration dates from deal text
function parseExpiryDate(str) {
  if (!str) return null;
  const isoMatch = str.match(/\b(202[5-9]-\d{2}-\d{2})\b/);
  if (isoMatch) return isoMatch[1];

  const monthNames = "(?:Jan(?:uary)?|Feb(?:ruary)?|Mar(?:ch)?|Apr(?:il)?|May|Jun(?:e)?|Jul(?:y)?|Aug(?:ust)?|Sep(?:tember)?|Oct(?:ober)?|Nov(?:ember)?|Dec(?:ember)?)";
  const mdyRegex = new RegExp(`\\b(${monthNames})\\s+(\\d{1,2})(?:st|nd|rd|th)?,?\\s+(202[5-9])\\b`, "i");
  const mdyMatch = str.match(mdyRegex);
  if (mdyMatch) {
    const monthMap = { jan: "01", feb: "02", mar: "03", apr: "04", may: "05", jun: "06", jul: "07", aug: "08", sep: "09", oct: "10", nov: "11", dec: "12" };
    const mStr = monthMap[mdyMatch[1].slice(0, 3).toLowerCase()];
    if (mStr) {
      return `${mdyMatch[3]}-${mStr}-${mdyMatch[2].padStart(2, '0')}`;
    }
  }

  const slashMatch = str.match(/\b(\d{1,2})[\/\-](\d{1,2})[\/\-](202[5-9])\b/);
  if (slashMatch) {
    return `${slashMatch[3]}-${slashMatch[1].padStart(2, '0')}-${slashMatch[2].padStart(2, '0')}`;
  }

  const daysMatch = str.match(/(?:expires?|ends?|valid)\s+in\s+(\d+)\s+days?/i);
  if (daysMatch) {
    const d = new Date();
    d.setDate(d.getDate() + parseInt(daysMatch[1], 10));
    return d.toISOString().split("T")[0];
  }
  return null;
}

// Helper to extract deals from a paragraph/sentence
function extractOffersFromText(text, defaultSource) {
  if (!text) return;
  const chunks = text.split(/\.\s+|\n+/);
  for (const c of chunks) {
    const str = c.trim();
    if (str.length < 20) continue;

    // Regex for discount percentage/dollar amount
    const discMatch = str.match(/(\b\d{1,2}%\s*(?:off|discount)\b|\bup to \d{1,2}%\s*off\b|\$\d+\s*(?:off|discount)\b|\bfree shipping\b)/i);
    const discountText = discMatch ? discMatch[0].toUpperCase() : null;

    // Regex for coupon code
    const codeMatch = str.match(/\*\*([A-Za-z0-9_-]{3,20})\*\*|code\s+["']?([A-Za-z0-9_-]{4,20})["']?|promo code\s+["']?([A-Za-z0-9_-]{4,20})["']?/i);
    let code = null;
    if (codeMatch) {
      const found = (codeMatch[1] || codeMatch[2] || codeMatch[3] || "").toUpperCase();
      if (found && !["FREE", "CODE", "DISCOUNT", "OFFER", "PROMO", "OFF"].includes(found)) {
        code = found;
      }
    }

    if (!discountText && !code) continue;
    if (code && seenCodes.has(code)) continue;
    if (code) seenCodes.add(code);

    let title = discountText ? `${discountText} at ${storeName}` : `Special Offer at ${storeName}`;
    if (/2-year|annual|yearly/i.test(str)) {
      title = discountText ? `${discountText} on Multi-Year Plans at ${storeName}` : `Plan Discount at ${storeName}`;
    } else if (/student|teacher|military|worker/i.test(str)) {
      title = `${discountText || 'Special Discount'} for Students & Verification`;
    }

    if (seenTitles.has(title)) continue;
    seenTitles.add(title);

    const endDate = parseExpiryDate(str);

    deals.push({
      advertiserId,
      advertiserName: storeName,
      network,
      title,
      description: str,
      type: code ? "voucher" : "deal",
      code: code || undefined,
      discountText: discountText || null,
      endDate: endDate || null,
      sourceName: defaultSource || "RetailMeNot / Web",
      confidenceScore: 0.95
    });
  }
}

// Extract from Tavily comprehensive answer
extractOffersFromText(answerText, "RetailMeNot / Web");

// Also extract from individual search result snippets
for (const r of results) {
  const siteName = r.title?.split(/[-|]/)[0]?.trim() || "Coupon Site";
  extractOffersFromText(r.content || "", siteName);
}

return [{
  json: {
    advertiserId,
    storeName,
    network,
    domain,
    foundCount: deals.length,
    deals: deals,
    requestPayload: {
      advertiserId,
      deals: deals
    }
  }
}];
